def _load_eject_record(target):
    """Load a project's eject receipt, or return None."""
    epath = _manifest_base(target) / EJECT_NAME
    if not epath.exists():
        return None
    try:
        return json.loads(epath.read_text())
    except (json.JSONDecodeError, OSError):
        return None
